package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.server.level.*;import net.minecraft.world.phys.*;import net.minecraft.world.*;
/** Uses the existing FPV native payload slot and HB inventory; no parallel inventory. */
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)
public final class Hg01Payload{
 public static boolean is(ItemStack s){return s.getItem() instanceof Hg01Item;}
 public static boolean supported(Entity e){return e.getClass()==CubedFpvDroneEntity.class||e instanceof HeavyBomberDroneEntity;}
 public static boolean allowed(Player p,Entity d){var owner=SbwCompat.resolveDroneOwner(d.level() instanceof ServerLevel l?l:null,d);return !owner.hasUuid()||owner.uuid().equals(p.getUUID())||p.hasPermissions(2);}
 @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.HIGH)public static void load(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.EntityInteract e){var p=e.getEntity();var d=e.getTarget();var held=p.getItemInHand(e.getHand());if(!is(held)||!SbwCompat.isDrone(d))return;e.setCanceled(true);e.setCancellationResult(InteractionResult.FAIL);if(!supported(d)||p.distanceToSqr(d)>64||!p.isAlive()||p.isSpectator()||!allowed(p,d))return;if(d.level().isClientSide){e.setCancellationResult(InteractionResult.SUCCESS);return;}if(install(d,p,held))e.setCancellationResult(InteractionResult.CONSUME);}
 public static boolean install(Entity d,Player p,ItemStack held){if(d.level().isClientSide||!supported(d)||!allowed(p,d)||!is(held)||held.isEmpty()||d.isRemoved()||!d.isAlive())return false;
  if(d instanceof HeavyBomberDroneEntity){var inv=new DroneInventoryContainer(d);int total=0,empty=-1;for(int i=0;i<inv.getContainerSize();i++){var s=inv.getItem(i);if(empty<0&&s.isEmpty())empty=i;if(is(s)||HeavyBomberDroneEntity.hgSupported(s))total+=s.getCount();}if(total>=HeavyBomberDroneEntity.MAX_BOMBS||empty<0)return false;inv.setItem(empty,held.copyWithCount(1));inv.saveToDrone();}
  else{if(!SbwCompat.getDroneCurrentItem(d).isEmpty())return false;SbwCompat.setDroneCurrentItem(d,held.copyWithCount(1));d.getEntityData().set(com.atsuishio.superbwarfare.entity.vehicle.DroneEntity.AMMO,1);d.getEntityData().set(com.atsuishio.superbwarfare.entity.vehicle.DroneEntity.MAX_AMMO,1);d.getEntityData().set(com.atsuishio.superbwarfare.entity.vehicle.DroneEntity.IS_KAMIKAZE,false);}
  SbwCompat.ensureDroneOwner(d,p);if(!p.getAbilities().instabuild)held.shrink(1);return true;
 }
 public static org.joml.Matrix4d fpvFrame(CubedFpvDroneEntity d,float t){return new org.joml.Matrix4d().translate(0,CubedFpvDroneRenderMath.attachmentBaseYOffset(),0).rotateY(Math.toRadians(CubedFpvDroneRenderMath.renderYawDegrees(d.getYaw(t)))).rotateX(Math.toRadians(CubedFpvDroneRenderMath.renderBodyPitchDegrees(d.getBodyPitch(t)))).rotateZ(Math.toRadians(CubedFpvDroneRenderMath.renderRollDegrees(d.getRoll(t))));}
 public static Vec3 releasePosition(CubedFpvDroneEntity d,int socket,float t){var v=d instanceof HeavyBomberDroneEntity?Hb01VisualPose.matrix(d.getYaw(t),d.getBodyPitch(t),d.getRoll(t)).transformPosition(Hb01VisualPose.socket(socket).add(0,-3.04/16,0)):fpvFrame(d,t).transformPosition(new org.joml.Vector3d(0,-.17-3.04/16,.18));var at=d.getPosition(t);return at.add(v.x,v.y,v.z);}
 private static boolean authorized(CubedFpvDroneEntity d,Player p){return p!=null&&p.isAlive()&&p.level()==d.level()&&SbwCompat.getDroneControllerUuid(d)!=null&&p.getUUID().equals(SbwCompat.getDroneControllerUuid(d))&&SbwCompat.isUsingLinkedMonitorForDrone(p,d)&&allowed(p,d)&&!DroneJammerSystem.isJammed(d)&&!DroneBatterySystem.isOutOfEnergyState(d)&&!d.isRemoved()&&d.isAlive()&&!Dc01Docking.docked(d);}
 public static void beforeTick(CubedFpvDroneEntity d){if(d.level().isClientSide||d instanceof HeavyBomberDroneEntity)return;boolean loaded=is(SbwCompat.getDroneCurrentItem(d))&&d.getEntityData().get(com.atsuishio.superbwarfare.entity.vehicle.DroneEntity.AMMO)>0;d.hgVisual(loaded?SbwCompat.getDroneCurrentItem(d).copyWithCount(1):ItemStack.EMPTY);if(loaded&&SbwCompat.getDroneFire(d)){var p=(Player)SbwCompat.getDroneController(d);SbwCompat.setDroneFire(d,false);if(authorized(d,p)&&spawn(d,p,0)){clearFpv(d);}}}
 public static boolean dropBomber(HeavyBomberDroneEntity d,DroneInventoryContainer inv,int slot,Player p){if(!authorized(d,p)||!is(inv.getItem(slot)))return false;if(!spawn(d,p,0))return false;var s=inv.getItem(slot);s.shrink(1);inv.setItem(slot,s.isEmpty()?ItemStack.EMPTY:s);inv.saveToDrone();return true;}
 private static boolean spawn(CubedFpvDroneEntity d,Player p,int socket){var g=AddonEntities.HG01.get().create(d.level());if(g==null)return false;g.arm(p,releasePosition(d,socket,1),d.getDeltaMovement().add(0,-.08,0));DroneAttackDamage.mark(g,d,"sbwdroneconfig:hand_grenade_hg01");DroneExplosionVfx.markPayload(g);return d.level().addFreshEntity(g);}
 private static void clearFpv(CubedFpvDroneEntity d){SbwCompat.setDroneCurrentItem(d,ItemStack.EMPTY);d.getEntityData().set(com.atsuishio.superbwarfare.entity.vehicle.DroneEntity.AMMO,0);d.getEntityData().set(com.atsuishio.superbwarfare.entity.vehicle.DroneEntity.DISPLAY_ENTITY,"");d.hgVisual(ItemStack.EMPTY);}
 public static void destroyed(CubedFpvDroneEntity d){if(d.level().isClientSide)return;if(d instanceof HeavyBomberDroneEntity){var inv=new DroneInventoryContainer(d);for(int i=0;i<inv.getContainerSize();i++){var s=inv.getItem(i);if(is(s)){var copy=s.copy();inv.setItem(i,ItemStack.EMPTY);d.hgDeathDrops.add(copy);}}inv.saveToDrone();}else if(is(SbwCompat.getDroneCurrentItem(d))){var s=SbwCompat.getDroneCurrentItem(d).copyWithCount(1);clearFpv(d);d.hgDeathDrops.add(s);}}
 public static void returnOnPickup(HeavyBomberDroneEntity d,Player p){var inv=new DroneInventoryContainer(d);for(int i=0;i<inv.getContainerSize();i++){var s=inv.getItem(i);if(is(s)){var copy=s.copy();inv.setItem(i,ItemStack.EMPTY);net.neoforged.neoforge.items.ItemHandlerHelper.giveItemToPlayer(p,copy);}}inv.saveToDrone();}
 public static void finishDrops(CubedFpvDroneEntity d){if(d.level().isClientSide)return;for(var s:java.util.List.copyOf(d.hgDeathDrops)){d.hgDeathDrops.remove(s);d.spawnAtLocation(s);}}
 private Hg01Payload(){}
}
